class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def transformTree(root):
    def reverse_inorder(node, summation):
        if not node:
            return summation
        summation = reverse_inorder(node.right, summation)
        node.val = summation = summation + node.val
        return reverse_inorder(node.left, summation)

    reverse_inorder(root, 0)
